cd /Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature; python3 - <<'PY'
import pathlib
p = pathlib.Path('src/codegen/lower_inst/builtins/io/phar_write.rs')
t = p.read_text()
OLD = '''            ctx.emitter.instruction("ldr x0, [sp, #0]");
            abi::emit_call_label(ctx.emitter, "__rt_close");
            ctx.emitter.instruction("ldr x0, [sp, #8]");'''
NEW = '''            // `__rt_php_wrapper_open` hands back a DESCRIPTOR, so the backend close is the one
            // that takes it: the same one every implicit destruction goes through.
            ctx.emitter.instruction("ldr x0, [sp, #0]");
            abi::emit_call_label(ctx.emitter, "__rt_stream_close_backend");
            ctx.emitter.instruction("ldr x0, [sp, #8]");'''
assert t.count(OLD) == 1
t = t.replace(OLD, NEW, 1)
OLD = '''            ctx.emitter.instruction("mov rdi, QWORD PTR [rsp + 0]");
            abi::emit_call_label(ctx.emitter, "__rt_close");
            ctx.emitter.instruction("mov rax, QWORD PTR [rsp + 8]");'''
NEW = '''            // See the AArch64 counterpart.
            ctx.emitter.instruction("mov rdi, QWORD PTR [rsp + 0]");
            abi::emit_call_label(ctx.emitter, "__rt_stream_close_backend");
            ctx.emitter.instruction("mov rax, QWORD PTR [rsp + 8]");'''
assert t.count(OLD) == 1
p.write_text(t.replace(OLD, NEW, 1))
print('the write route closes what it opened')
